// Keep prize labels near their badge, inside the art area, and out of each
// other's way. If a small quadrant fills up, use another short wave.
export function layoutWinFlights(items, area, obstacles = []) {
  const gap = 4;
  const waves = [];
  const output = [];
  const intersects = (a, b) => a.left < b.left + b.width + gap
    && a.left + a.width + gap > b.left
    && a.top < b.top + b.height + gap
    && a.top + a.height + gap > b.top;

  // Reserve the widest amounts first; preserve badge identity in the output.
  const ordered = items.map((item, index) => ({ ...item, index }))
    .sort((a, b) => b.width - a.width || a.index - b.index);
  for (const item of ordered) {
    const candidates = [];
    for (let top = area.top; top + item.height <= area.bottom; top += 3) {
      for (let left = area.left; left + item.width <= area.right; left += 3) {
        const rect = { left, top, width: item.width, height: item.height };
        if (obstacles.some(obstacle => intersects(rect, obstacle))) continue;
        const dx = left + item.width / 2 - item.x;
        const dy = top + item.height / 2 - item.y;
        // Favor a modest upward flight, then the nearest free side.
        const score = dx * dx + (dy + 18) ** 2;
        candidates.push({ ...rect, score });
      }
    }
    candidates.sort((a, b) => a.score - b.score);
    let choice;
    let wave = 0;
    for (; wave <= waves.length; wave++) {
      choice = candidates.find(candidate => !(waves[wave] || [])
        .some(placed => intersects(candidate, placed)));
      if (choice) break;
    }
    // If no free position exists, the caller leaves this prize to the badge's
    // manual popup. Never cover the receipt or center to force a flight.
    if (!choice) { output[item.index] = null; continue; }
    waves[wave] ||= [];
    const slot = waves[wave].length;
    waves[wave].push(choice);
    output[item.index] = { left: choice.left, top: choice.top, slot, wave };
  }
  const starts = [];
  waves.forEach((wave, index) => {
    starts[index] = index === 0 ? 0
      : starts[index - 1] + 1300 + (waves[index - 1].length - 1) * 60;
  });
  return output.map(position => {
    if (!position) return null;
    const { slot, ...rest } = position;
    return { ...rest, delay: starts[position.wave] + slot * 60 };
  });
}
